import{_ as d,c as e,o,b2 as r}from"./chunks/framework.CUhoHPxN.js";const p=JSON.parse('{"title":"业务页面总览","description":"","frontmatter":{},"headers":[],"relativePath":"docs/frontend/modules/index.md","filePath":"docs/frontend/modules/index.md"}'),c={name:"docs/frontend/modules/index.md"};function a(i,t,l,s,n,h){return o(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="业务页面总览" tabindex="-1">业务页面总览 <a class="header-anchor vp-link" href="#业务页面总览" aria-label="Permalink to &quot;业务页面总览&quot;">​</a></h1><p><code>quick-ui/src/views</code> 与后端菜单、API 的对应关系。路由 path 以实际 <code>getRouters</code> 为准。</p><h2 id="根级页面" tabindex="-1">根级页面 <a class="header-anchor vp-link" href="#根级页面" aria-label="Permalink to &quot;根级页面&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>文件</th><th>说明</th></tr></thead><tbody><tr><td><code>index.vue</code></td><td>首页仪表盘</td></tr><tr><td><code>login.vue</code></td><td>登录（验证码/手机/二维码、<strong>第三方 OAuth 登录</strong>）</td></tr><tr><td><code>redirect/index.vue</code></td><td>路由重定向</td></tr><tr><td><code>error/401.vue</code>、<code>404.vue</code></td><td>错误页</td></tr></tbody></table></div><h2 id="系统管理-system" tabindex="-1">系统管理（<code>system/</code>） <a class="header-anchor vp-link" href="#系统管理-system" aria-label="Permalink to &quot;系统管理（`system/`）&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>目录/文件</th><th>API 模块</th><th>后端 Controller</th></tr></thead><tbody><tr><td><code>user/index.vue</code> 等</td><td><code>api/system/user.js</code></td><td><code>SysUserController</code></td></tr><tr><td><code>role/index.vue</code></td><td><code>api/system/role.js</code></td><td><code>SysRoleController</code></td></tr><tr><td><code>dept/</code></td><td><code>api/system/dept.js</code></td><td><code>SysDeptController</code></td></tr><tr><td><code>menu/</code></td><td><code>api/system/menu.js</code></td><td><code>SysMenuController</code></td></tr><tr><td><code>dict/type</code>、<code>dict/data</code></td><td><code>api/system/dict/*</code></td><td><code>DictType/DataController</code></td></tr><tr><td><code>config/index.vue</code></td><td><code>api/system/config.js</code></td><td><code>SysConfigController</code></td></tr><tr><td><code>notice/index.vue</code></td><td><code>api/system/notice.js</code></td><td><code>SysNoticeController</code></td></tr><tr><td><strong><code>oauthClient/index.vue</code></strong></td><td><code>api/system/oauthClient.js</code></td><td><code>SysOauthClientController</code></td></tr><tr><td><strong><code>oauthProvider/index.vue</code></strong></td><td><code>api/system/oauthProvider.js</code></td><td><code>SysOauthProviderController</code></td></tr><tr><td><code>user/profile/</code></td><td>—</td><td>个人中心、改密、头像</td></tr></tbody></table></div><p><strong>列表页参考模板</strong>：<code>system/config/index.vue</code>（C7JsonTable + 查询区 + 工具栏）。</p><h2 id="系统监控-monitor" tabindex="-1">系统监控（<code>monitor/</code>） <a class="header-anchor vp-link" href="#系统监控-monitor" aria-label="Permalink to &quot;系统监控（`monitor/`）&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>页面</th><th>API</th><th>后端</th></tr></thead><tbody><tr><td><code>online/index.vue</code></td><td><code>api/monitor/online.js</code></td><td><code>SysUserOnlineController</code></td></tr><tr><td><code>operlog/index.vue</code></td><td><code>api/monitor/operlog.js</code></td><td><code>SysOperLogController</code></td></tr><tr><td><code>logininfor/index.vue</code></td><td><code>api/monitor/logininfor.js</code></td><td><code>SysLogininforController</code></td></tr><tr><td><code>job/index.vue</code></td><td><code>api/monitor/job.js</code></td><td><code>SysJobController</code></td></tr><tr><td><code>job-log/index.vue</code></td><td><code>api/monitor/jobLog.js</code></td><td><code>SysJobLogController</code></td></tr></tbody></table></div><h2 id="系统工具-tool-gen" tabindex="-1">系统工具（<code>tool/gen/</code>） <a class="header-anchor vp-link" href="#系统工具-tool-gen" aria-label="Permalink to &quot;系统工具（`tool/gen/`）&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>页面</th><th>说明</th></tr></thead><tbody><tr><td><code>index.vue</code></td><td>表列表、导入、生成</td></tr><tr><td><code>edit.vue</code></td><td>生成配置编辑</td></tr><tr><td><code>components/*Dialog.vue</code></td><td>导入表、预览代码、在线建表</td></tr></tbody></table></div><p>API：<code>api/tool/gen.js</code> → <code>GenController</code>。</p><h2 id="oauth-oauth" tabindex="-1">OAuth（<code>oauth/</code>） <a class="header-anchor vp-link" href="#oauth-oauth" aria-label="Permalink to &quot;OAuth（`oauth/`）&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>页面</th><th>说明</th></tr></thead><tbody><tr><td><strong><code>authorize.vue</code></strong></td><td>用户授权确认；同意后跳转后端 <code>/oauth2/doConfirm</code></td></tr></tbody></table></div><p>登录页联邦：<code>login.vue</code> 调用 <code>api/oauth/authorize.js</code> → <code>GET /oauth/login/providers</code>。</p><h2 id="开发演示-dev" tabindex="-1">开发演示（<code>dev/</code>） <a class="header-anchor vp-link" href="#开发演示-dev" aria-label="Permalink to &quot;开发演示（`dev/`）&quot;">​</a></h2><p>C7 组件 E2E 页，菜单由后端动态下发，例如：</p><ul><li><code>C7JsonTableE2E</code>、<code>C7JsonTableColumnE2E</code></li><li><code>C7DatePickerE2E</code>、<code>C7DialogE2E</code>、<code>C7DictTagE2E</code></li><li><code>C7ButtonE2E</code>、<code>C7CardE2E</code>、<code>C7WatermarkE2E</code> 等</li></ul><p>用于组件回归与文档示例对照。</p><hr><h2 id="api-模块索引-src-api" tabindex="-1">API 模块索引（<code>src/api</code>） <a class="header-anchor vp-link" href="#api-模块索引-src-api" aria-label="Permalink to &quot;API 模块索引（`src/api`）&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>文件</th><th>用途</th></tr></thead><tbody><tr><td><code>login.js</code></td><td>登录、验证码、getInfo、logout</td></tr><tr><td><code>menu.js</code></td><td>getRouters</td></tr><tr><td><code>oauth/authorize.js</code></td><td>登录页 IdP 列表</td></tr><tr><td><code>system/*.js</code></td><td>系统管理各域</td></tr><tr><td><code>monitor/*.js</code></td><td>监控与任务</td></tr><tr><td><code>tool/gen.js</code></td><td>代码生成</td></tr></tbody></table></div><hr><h2 id="全局能力-非-views" tabindex="-1">全局能力（非 views） <a class="header-anchor vp-link" href="#全局能力-非-views" aria-label="Permalink to &quot;全局能力（非 views）&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>能力</th><th>位置</th></tr></thead><tbody><tr><td>Client HMAC</td><td><code>utils/clientSign.js</code> + <code>request.js</code></td></tr><tr><td>字典</td><td><code>utils/dict.js</code> → <code>useDict</code></td></tr><tr><td>权限指令</td><td><code>directive/permission/hasPermi.js</code></td></tr><tr><td>页签</td><td><code>plugins/tab.js</code></td></tr><tr><td>弹窗封装</td><td><code>plugins/modal.js</code></td></tr></tbody></table></div><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor vp-link" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./../index.html" class="vp-link">前端概述</a></li><li><a href="./../../backend/modules/oauth2.html" class="vp-link">OAuth2 集成</a></li><li><a href="./../../backend/modules/index.html" class="vp-link">后端功能模块</a></li></ul>',28)])])}const v=d(c,[["render",a]]);export{p as __pageData,v as default};
